#!/bin/bash
# Generated by bin/build-installer.py. Edit installer/install-propainter.template.sh.
set -euo pipefail
UPSTREAM_COMMIT=e870e79321c31b733e2031af5aa2fb1fe3ac7eec
UV_VERSION=0.11.14
DEST="$HOME/src/scrubber"
SMOKE=1
usage() {
  cat <<'HELP'
Install ProPainter for Apple Silicon macOS (M1/M2/M3/M4 and newer).
Usage: bash install-propainter.sh [--dir PATH] [--skip-smoke-test]
Default destination: ~/src/scrubber
Installs an isolated Python 3.12 environment, pinned dependencies, launchers,
and verified model weights. Runs a six-frame repair by default.
No Homebrew, administrator access, or preinstalled Python required.
HELP
}
fail() { printf 'Error: %s\n' "$*" >&2; exit 1; }
while [ "$#" -gt 0 ]; do
  case "$1" in
    --dir) [ "$#" -ge 2 ] && [ -n "$2" ] || fail '--dir needs a path'; DEST="$2"; shift 2 ;;
    --skip-smoke-test) SMOKE=0; shift ;;
    -h|--help) usage; exit 0 ;;
    *) fail "Unknown argument: $1 (use --help)" ;;
  esac
done
[ "$(uname -s)" = Darwin ] || fail 'This installer is for macOS.'
[ "$(uname -m)" = arm64 ] || fail 'Run from a native Apple Silicon terminal, not Rosetta.'
mkdir -p "$DEST"
DEST=$(cd "$DEST" && pwd -P)
WORK=$(mktemp -d "${TMPDIR:-/tmp}/scrubber-install.XXXXXX")
trap 'rm -rf "$WORK"' EXIT
trap 'printf "Installation interrupted; rerun the same command to resume.\n" >&2; exit 130' INT TERM
mkdir -p "$DEST/.cache" "$DEST/.tools"
# Concurrent installation into one destination can corrupt its environment.
LOCK="$DEST/.cache/install.lock"
mkdir "$LOCK" 2>/dev/null || fail "Another install may be running. If none is running, remove $LOCK and retry."
trap 'rm -rf "$WORK"; rmdir "$LOCK"' EXIT

# Embedded files are generated from the tracked, tested launcher and lockfile.
mkdir "$WORK/payload"
base64 -D <<'SCRUBBER_PAYLOAD' | tar -xz -C "$WORK/payload"
H4sIAAAAAAAC/+1XW2/bNhTus34Fpw2otVqyJV9yQQWsydK1WNoEafcwBIHAyJTFWhJVknKsFv3v
