SCRUBBER_PAYLOAD
for file in requirements-macos.lock run_propainter.py bin/propainter bin/smoke-test; do
  if [ -e "$DEST/$file" ]; then
    cmp -s "$WORK/payload/$file" "$DEST/$file" || fail "Existing $DEST/$file differs; use another --dir to preserve your changes."
  fi
done

printf '\nInstalling into %s\n' "$DEST"
# Keep uv and its Python installations local; no shell-profile changes.
UV="$DEST/.tools/uv"
if [ ! -x "$UV" ]; then
  curl --fail --location --retry 3 "https://astral.sh/uv/$UV_VERSION/install.sh" -o "$WORK/uv-install.sh"
  UV_UNMANAGED_INSTALL="$DEST/.tools" sh "$WORK/uv-install.sh"
fi
export UV_CACHE_DIR="$DEST/.cache/uv"
export UV_PYTHON_INSTALL_DIR="$DEST/.tools/python"
export UV_PYTHON_BIN_DIR="$DEST/.tools/bin"

if [ -d "$DEST/ProPainter/.git" ]; then
  actual=$(git -C "$DEST/ProPainter" rev-parse HEAD)
  [ "$actual" = "$UPSTREAM_COMMIT" ] || fail 'Existing ProPainter checkout is at another revision; use a new --dir.'
  [ -z "$(git -C "$DEST/ProPainter" status --porcelain --untracked-files=no)" ] || fail 'Existing ProPainter has source edits; use a new --dir.'
elif [ -e "$DEST/ProPainter" ]; then
  [ -f "$DEST/ProPainter/.scrubber-upstream-commit" ] || fail 'Unrecognised ProPainter directory; use a new --dir.'
  [ "$(cat "$DEST/ProPainter/.scrubber-upstream-commit")" = "$UPSTREAM_COMMIT" ] || fail 'Installed source revision differs; use a new --dir.'
else
  printf '\nDownloading pinned ProPainter source...\n'
  curl --fail --location --retry 3 "https://codeload.github.com/sczhou/ProPainter/tar.gz/$UPSTREAM_COMMIT" -o "$WORK/source.tar.gz"
  mkdir "$WORK/source"
  tar -xzf "$WORK/source.tar.gz" --strip-components=1 -C "$WORK/source"
  printf '%s\n' "$UPSTREAM_COMMIT" > "$WORK/source/.scrubber-upstream-commit"
  mv "$WORK/source" "$DEST/ProPainter"
fi
if [ -e "$DEST/.venv" ]; then
  [ -x "$DEST/.venv/bin/python" ] || fail 'Existing .venv is incomplete; choose a new --dir or repair it first.'
  "$DEST/.venv/bin/python" -c 'import sys, platform; assert sys.version_info[:2] == (3,12) and platform.machine() == "arm64", "Python 3.12 arm64 required"'
else
  "$UV" venv --python 3.12 --managed-python "$DEST/.venv"
fi
# Files are copied only after all existing versions have been checked.
mkdir -p "$DEST/bin"
for file in requirements-macos.lock run_propainter.py bin/propainter bin/smoke-test; do
  cp "$WORK/payload/$file" "$DEST/$file"
done
chmod +x "$DEST/bin/propainter" "$DEST/bin/smoke-test"
"$UV" pip sync --python "$DEST/.venv/bin/python" "$DEST/requirements-macos.lock"
"$UV" pip check --python "$DEST/.venv/bin/python"

mkdir -p "$DEST/ProPainter/weights"
while read -r name expected; do
  target="$DEST/ProPainter/weights/$name"
  if [ -f "$target" ]; then
    actual=$(shasum -a 256 "$target" | awk '{print $1}')
    [ "$actual" = "$expected" ] || fail "Checksum mismatch for existing $target; move it aside and retry."
    printf 'Verified existing %s\n' "$name"
    continue
  fi
  curl --fail --location --retry 3 "https://github.com/sczhou/ProPainter/releases/download/v0.1.0/$name" -o "$WORK/$name"
  actual=$(shasum -a 256 "$WORK/$name" | awk '{print $1}')
  [ "$actual" = "$expected" ] || fail "Checksum mismatch for downloaded $name"
  mv "$WORK/$name" "$target"
done <<'WEIGHTS'
ProPainter.pth 12c070c4b48f374c91d8a2a17851140b85c159621080989f9e191bbc18bd6591
raft-things.pth fcfa4125d6418f4de95d84aec20a3c5f4e205101715a79f193243c186ac9a7e1
recurrent_flow_completion.pth 22939a1a7900da878dbe1ccd011d646b1bfb30b8290039d8ff0e0c2fefbfd283
WEIGHTS
"$DEST/.venv/bin/python" - <<'PY'
import torch
print('PyTorch:', torch.__version__)
print('Apple GPU available:', torch.backends.mps.is_available())
if not torch.backends.mps.is_available():
    raise SystemExit('Apple GPU unavailable. Check macOS/PyTorch support before running ProPainter.')
PY
"$DEST/bin/propainter" --help > "$WORK/help.txt"
if [ "$SMOKE" = 1 ]; then
  printf '\nRunning sample repair (first launch may build caches)...\n'
  "$DEST/bin/smoke-test"
  "$DEST/.venv/bin/python" - "$DEST/results/smoke/frames/inpaint_out.mp4" <<'PY'
import sys
import torchvision
frames, _, info = torchvision.io.read_video(sys.argv[1], pts_unit='sec')
assert tuple(frames.shape) == (6, 192, 320, 3), frames.shape
assert info['video_fps'] == 24, info
print('Verified sample export: six 320x192 frames at 24 fps.')
PY
fi
printf '\nInstallation complete.\nLauncher: %s/bin/propainter\nSample test: %s/bin/smoke-test\n' "$DEST" "$DEST"
printf 'Upstream exports silent video and resizes the whole frame; crop/composite and audio preservation are not included.\n'
printf 'License: ProPainter/LICENSE (S-Lab, non-commercial use).\n'
